import { announcements, filterCharacters, formatNumber as n, leaderboardCategories } from './data.mjs';

export const escapeHTML = value => String(value).replace(/[&<>"']/g, character => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[character]));
const paths = {
  grid: '<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',
  sword: '<path d="m15 3 6 0 0 6-11 11-6-6Z"/><path d="m2 13 9 9M3 21l4-4M15 3l6 6"/>',
  bell: '<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',
  plug: '<path d="m7 3 0 5m10-5v5M5 8h14v3a7 7 0 0 1-14 0Zm7 10v4"/>',
  arrow: '<path d="M4 12h16m-6-6 6 6-6 6"/>',
  chevron: '<path d="m9 5 7 7-7 7"/>',
  refresh: '<path d="M20 7v5h-5M4 17v-5h5M6 7a7 7 0 0 1 12-2l2 3M4 16l2 3a7 7 0 0 0 12-2"/>',
  logout: '<path d="M10 3H4v18h6M9 12h12m-5-5 5 5-5 5"/>',
  search: '<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',
  shield: '<path d="m12 2 8 4v6c0 5-8 10-8 10S4 17 4 12V6Z"/><path d="m8 12 3 3 5-6"/>',
  info: '<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7v1"/>',
  menu: '<path d="M4 6h16M4 12h16M4 18h16"/>',
  close: '<path d="m6 6 12 12M6 18 18 6"/>',
  diamond: '<path d="m12 2 9 10-9 10-9-10Z"/><path d="m7 12 5 5 5-5-5-5Z"/>',
  user: '<circle cx="12" cy="8" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3"/>',
  eye: '<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>',
  coat: '<path d="m8 3 4 3 4-3 6 5-4 5-2-2v10H8V11l-2 2-4-5Z"/>',
  shoulder: '<path d="m3 7 9-4 9 4-3 10-6 4-6-4Z"/><path d="M3 7l9 6 9-6M12 13v8"/>',
  pants: '<path d="M6 3h12l2 18h-6l-2-10-2 10H4Z"/><path d="M6 7h12"/>',
  shoes: '<path d="M5 3h7v10l8 3 1 5H3v-6l2-3Z"/><path d="M3 17h17"/>',
  ring: '<circle cx="12" cy="14" r="7"/><path d="m8 4 4-3 4 3-4 5Z"/>',
  heart: '<path d="M12 21S2 14 2 8a5 5 0 0 1 10-1 5 5 0 0 1 10 1c0 6-10 13-10 13Z"/>',
  spark: '<path d="m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3Z"/>',
};
export const icon = (name, className = '') => `<svg class="icon ${className}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name] || paths.diamond}</svg>`;
const badge = (label = '演示数据') => `<span class="demo-tag">${label}</span>`;
const logo = () => `<img class="brand-mark" src="./mark.svg" width="38" height="38" alt=""><div><strong>阿拉德档案</strong><span>ARAD ARCHIVE</span></div>`;

export function characterArt(character, suffix = '') {
  const id = `${character.id}-${suffix}`;
  const colors = character.theme === 'fighter' ? ['#60877b', '#a9d3ba'] : character.theme === 'gunner' ? ['#747ea1', '#bdc8e0'] : ['#94775a', '#d3b17b'];
  return `<svg viewBox="0 0 440 420" class="character-art ${character.theme}" role="img" aria-label="${escapeHTML(character.family)}原创抽象剪影插画">
    <defs><radialGradient id="glow-${id}"><stop stop-color="${colors[0]}" stop-opacity=".42"/><stop offset="1" stop-color="${colors[0]}" stop-opacity="0"/></radialGradient><linearGradient id="blade-${id}" x1="0" y1="0" x2="1" y2="1"><stop stop-color="${colors[1]}"/><stop offset=".5" stop-color="#6d706e"/><stop offset="1" stop-color="#292c2d"/></linearGradient><linearGradient id="cloak-${id}"><stop stop-color="#22292c"/><stop offset="1" stop-color="#111416"/></linearGradient></defs>
    <circle cx="238" cy="174" r="192" fill="url(#glow-${id})"/>
    <g fill="none" stroke="${colors[0]}" opacity=".36"><circle cx="238" cy="181" r="136"/><circle cx="238" cy="181" r="125" stroke-dasharray="1 11"/><path d="M238 26v33M238 306v33M83 181h32M360 181h32M132 75l22 22M324 267l22 22M344 75l-22 22M154 267l-22 22"/><path d="m238 45 118 204H120Z" opacity=".3"/></g>
    <path d="m181 420 24-122 71-34 24 156Z" fill="#101314"/><path d="m180 175 47-34 57 20 28 88-18 172H116l27-74Z" fill="url(#cloak-${id})"/>
    <path d="m181 174-22 86-41 114 68-24 38-119 44 37 8 149h67l-18-113-39-145-51-9Z" fill="#1d2224"/>
    <path d="m178 176 43 19 48-32-23 53-40 12-49-26Z" fill="#3e4241"/><path d="m179 178 43 16 44-29M173 184l39 18M221 202l36-26M202 228l-27 106" stroke="${colors[0]}" fill="none" stroke-width="2"/>
    <path d="m207 101 37-8 29 25-8 37-30 17-27-26Z" fill="#383b38"/><path d="m203 109 18-35 37 3 24 29-20 15-12-22-25 23-17 33-8-20Z" fill="#96958b"/><path d="m210 102 11-28 37 3 15 19-24-11-23 19-17 26Z" fill="#c1beb0"/><path d="m252 118 13 5-10 10-18 7" stroke="#b7a68d" stroke-width="2" fill="none"/><path d="m239 145 20-9-4 16-20 13Z" fill="#252b2a"/>
    <path d="m167 191-27 12-13 60 21 18 26-46 12-39Z" fill="#454543"/><path d="m127 262-10 36 15 12 20-24-4-16Z" fill="#7c7666"/><path d="m277 181 28 23 18 53-19 18-33-43-9-38Z" fill="#333a3c"/><path d="m304 256-18 22 7 22 26-8 7-20Z" fill="#7d786c"/>
    ${character.theme === 'fighter' ? `<g fill="none" stroke="${colors[1]}" opacity=".7"><circle cx="128" cy="284" r="28"/><circle cx="314" cy="276" r="32"/><circle cx="314" cy="276" r="39" stroke-dasharray="8 10"/></g>` : character.theme === 'gunner' ? `<path d="m103 273 25-3 4 45-8 22h-14l4-32-19-9Z" fill="url(#blade-${id})"/><path d="m286 276 37-9 12 14-40 10 5 27-14 1Z" fill="url(#blade-${id})"/>` : `<path d="m132 277 15 7-87 123-22 13 5-29Z" fill="url(#blade-${id})"/><path d="m108 275 44 23 5-11-43-23Z" fill="#a89878"/><path d="m137 275 18-31 7 4-14 33Z" fill="#4e4a3e"/><path d="m45 400 85-112" stroke="#e4d1a9" stroke-opacity=".65"/>`}
    <path d="M69 418h311" stroke="${colors[0]}" opacity=".6"/><g fill="${colors[1]}" opacity=".6"><circle cx="95" cy="234" r="1.5"/><circle cx="343" cy="112" r="1.2"/><circle cx="361" cy="296" r="1.7"/><circle cx="156" cy="95" r="1"/><circle cx="87" cy="342" r="1.3"/></g>
  </svg>`;
}

function login() {
  const artCharacter = { id: 'entry', family: '冒险者', theme: 'sword' };
  return `<div class="entry-shell"><header class="entry-header"><a href="#" class="brand" aria-label="阿拉德档案首页">${logo()}</a><span class="entry-version">PLAYER PORTAL <b> / </b> PROTOTYPE 01</span></header>
    <main id="main-content" class="entry-main"><section class="entry-story"><div class="eyebrow"><span></span> YOUR ADVENTURE, AT A GLANCE</div><h1>冒险有迹可循。<br><em>你的阿拉德，</em><br>一目了然。</h1><p>角色、装备与旅途中的每一次成长。<br>在这里，重新认识你的冒险。</p><div class="entry-art">${characterArt(artCharacter, 'login')}<span class="vertical-caption">THE JOURNEY CONTINUES</span></div><div class="entry-footnote">一个全新、独立的 DNF 玩家门户原型</div></section>
    <section class="entry-card" aria-labelledby="entry-title"><div class="entry-symbol">${icon('diamond')}</div><div class="eyebrow">WELCOME, ADVENTURER</div><h2 id="entry-title">欢迎回来，冒险家</h2><p class="muted">先逛一逛属于你的角色档案。</p><div class="entry-demo-notice">${icon('info')}<div><strong>当前为交互演示</strong><span>未连接游戏服务器 · 不收集真实账号密码</span></div></div><div class="sample-account"><div class="avatar">旅</div><div><span>演示账号：admin</span><strong>无需密码 <small>DEMO</small></strong></div>${icon('shield')}</div><form id="demo-login-form" novalidate><label class="demo-login-label" for="demo-username">演示用户名</label><input id="demo-username" class="demo-login-input" name="username" type="text" placeholder="请输入 admin" required maxlength="40" autocomplete="off" autocapitalize="none" spellcheck="false" aria-describedby="demo-login-hint demo-login-error" aria-invalid="false"><p id="demo-login-hint" class="demo-login-hint">仅接受小写 admin，忽略首尾空格。</p><p id="demo-login-error" class="demo-login-error" role="alert" hidden></p><button id="demo-login-button" class="primary-button full" type="submit">登录演示 ${icon('arrow')}</button></form><p class="entry-privacy">尚未接入真实身份验证。admin 不赋予管理或 GM 权限。<br>所有角色与数值均为虚构样例。</p><div class="entry-features"><span>${icon('eye')} 只读预览</span><span>${icon('sword')} 3 个示例角色</span><span>${icon('shield')} 不操作游戏</span></div></section></main><footer class="entry-footer"><span>阿拉德档案 · 非官方玩家门户概念演示</span><span>DESIGNED FOR THE ADVENTURE</span></footer></div>`;
}

const navItems = [['overview', 'grid', '冒险总览'], ['characters', 'sword', '我的角色'], ['leaderboard', 'diamond', '排行榜'], ['announcements', 'bell', '公告中心'], ['connection', 'plug', '接入说明']];
function sidebar(state) {
  return `<aside class="sidebar ${state.menuOpen ? 'is-open' : ''}" aria-label="主导航"><a class="brand" href="#" data-action="nav" data-view="overview">${logo()}</a><div class="sidebar-section-label">PLAYER CENTER</div><nav>${navItems.map(([view, ico, label]) => `<button class="nav-item ${state.view === view ? 'active' : ''}" data-action="nav" data-view="${view}" ${state.view === view ? 'aria-current="page"' : ''}>${icon(ico)}<span>${label}</span>${view === 'announcements' ? '<small>3</small>' : ''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="connection-small"><span class="status-dot"></span><strong>演示模式</strong><p>未连接游戏服务器<br>仅展示静态样例数据</p></div><button class="sidebar-account" data-action="logout"><span class="avatar small">旅</span><span><strong>${escapeHTML(state.account.displayName)}</strong><small>退出演示 / 重置</small></span>${icon('logout')}</button><span class="sidebar-version">ARAD ARCHIVE &nbsp; / &nbsp; v0.1.0</span></div></aside>${state.menuOpen ? '<button class="sidebar-backdrop" data-action="menu" aria-label="关闭导航"></button>' : ''}`;
}
function pageHeading(eyebrow, title, description, action = '') { return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1 tabindex="-1" id="page-title">${title}</h1><p>${description}</p></div>${action}</div>`; }
function sectionHeading(title, subtitle = '', link = '') { return `<div class="section-heading"><div><h2>${title}</h2>${subtitle ? `<p>${subtitle}</p>` : ''}</div>${link}</div>`; }
function characterCard(character, selected = false) {
  return `<button class="character-card theme-${character.theme} ${selected ? 'selected' : ''}" data-action="select" data-id="${character.id}" aria-label="查看${escapeHTML(character.name)}的演示详情"><div class="card-top"><span class="character-family">${character.family}</span><span class="level-badge">Lv. ${character.level}</span></div><div class="card-art">${characterArt(character, 'card')}<span class="character-watermark" aria-hidden="true">${character.initials}</span></div><div class="character-card-info"><span class="subtle-label">${character.tag} · 示例</span><h3>${character.name} ${icon('arrow')}</h3><p>${character.job}</p><div class="card-meta"><span>${icon('diamond')} 示例装备 <b>${character.equipment.length} 件</b></span><span class="unknown-dot">在线未知</span></div></div></button>`;
}
function announcementRows(limit = 3) { return announcements.slice(0, limit).map(a => `<button class="announcement-row" data-action="announcement" data-id="${a.id}"><span class="announcement-type ${a.pinned ? 'gold' : ''}">${a.type}</span><span class="announcement-copy"><strong>${a.title}${a.pinned ? '<em>置顶</em>' : ''}</strong><span>${a.summary}</span></span><span class="announcement-date">${a.date}</span>${icon('chevron')}</button>`).join(''); }

function overview(state) {
  const main = state.characters[0];
  return `${pageHeading('ADVENTURER OVERVIEW', '欢迎回来，冒险家', '在下一次出发之前，看看你的冒险档案。', '<button class="secondary-button" data-action="refresh">'+icon('refresh')+' 重载演示数据</button>')}
    <section class="overview-hero"><div class="hero-grid" aria-hidden="true"></div><div class="hero-copy"><span class="hero-kicker">YOUR MAIN CHARACTER <span>主角色 · 示例</span></span><h2>${main.name}</h2><div class="hero-job"><span>Lv. ${main.level}</span><i></i>${main.job}</div><p>剑锋所指，皆为前路。</p><button class="primary-button" data-action="select" data-id="${main.id}">查看角色档案 ${icon('arrow')}</button><div class="hero-bottom"><span>${icon('diamond')} 示例装备 <strong>${main.equipment.length} 件</strong></span><span class="hero-divider"></span><span>角色在线状态 <b>未知</b></span></div></div><div class="hero-art">${characterArt(main, 'hero')}</div><span class="hero-outline" aria-hidden="true">剑</span><div class="hero-caption"><span>01 / 03</span> GHOST SWORDSMAN</div></section>
    <section class="metric-grid" aria-label="演示账号摘要"><article class="metric-card"><span class="metric-icon">${icon('user')}</span><div><p>当前账号 <span>示例</span></p><strong class="account-value">${escapeHTML(state.account.username)}</strong><small>独立演示会话，非真实登录</small><button class="checkin-entry" data-action="checkin-info" aria-expanded="${state.checkinOpen}" aria-controls="checkin-note">签到 ${icon('chevron')}</button><p id="checkin-note" class="checkin-note" role="status" ${state.checkinOpen ? '' : 'hidden'}>签到尚未接入，奖励与重置时间待配置。不会发放点券或创建签到记录。</p></div></article><article class="metric-card"><span class="metric-icon">${icon('sword')}</span><div><p>角色数量 <span>示例</span></p><strong>03 <em>位冒险者</em></strong><small>查看并切换你的示例角色</small></div></article><article class="metric-card"><span class="metric-icon neutral">${icon('plug')}</span><div><p>数据连接</p><strong class="connection-value">未连接</strong><small>演示快照 · 游戏状态未知</small></div></article></section>
    <section>${sectionHeading('我的角色', '每一段旅途，都值得被记住。以下为虚构示例。', '<button class="text-button" data-action="nav" data-view="characters">全部角色 '+icon('arrow')+'</button>')}<div class="character-grid">${state.characters.map(c => characterCard(c)).join('')}</div></section>
    <section class="announcements-panel">${sectionHeading('冒险者公告', '关于这个新门户的最新说明', '<button class="text-button" data-action="nav" data-view="announcements">查看全部 '+icon('arrow')+'</button>')}<div class="announcement-list">${announcementRows(2)}</div></section>`;
}

function statPanel(c) { return `<div class="stats-main"><div class="resource-row"><div><span>${icon('heart')} 生命值 HP</span><strong>${n(c.hp)}</strong></div><div class="resource-bar hp"><i style="width:100%"></i></div></div><div class="resource-row"><div><span>${icon('spark')} 魔法值 MP</span><strong>${n(c.mp)}</strong></div><div class="resource-bar mp"><i style="width:100%"></i></div></div><div class="fatigue"><span>疲劳值 <b>${c.fatigue} <em>/ ${c.fatigueMax}</em></b></span><div class="resource-bar"><i style="width:${Math.round(c.fatigue / c.fatigueMax * 100)}%"></i></div></div></div><div class="attribute-grid">${[['力量', c.strength], ['智力', c.intelligence], ['示意攻击力', c.attack], ['示意防御力', c.defense]].map(([k, v]) => `<div><span>${k}</span><strong>${n(v)}</strong></div>`).join('')}</div><p class="inline-note">${icon('info')} 属性为设计示意，不是游戏中的实时或最终战斗数值。</p>`; }
function equipmentPanel(c) { return `<div class="equipment-grid">${c.equipment.map(([ico, slot, name, quality, reinforcement, stat]) => `<article class="equipment-item"><div class="equipment-icon ${quality === '传说' ? 'legendary' : ''}">${icon(ico === 'weapon' ? 'sword' : ico)}<span>${reinforcement}</span></div><div><span class="equipment-slot">${slot} <em>${quality} · 示例</em></span><h3>${name}</h3><p>${stat}</p></div></article>`).join('')}</div><p class="inline-note">${icon('info')} 装备名称、品质、强化与属性均为虚构样例，不对应已验证的游戏物品。</p>`; }
function charactersView(state) {
  const c = state.characters.find(c => c.id === state.selectedId) || state.characters[0];
  const filtered = filterCharacters(state.characters, state.query);
  return `${pageHeading('CHARACTER ARCHIVE', '我的角色', '切换角色，查看只属于这个示例账号的演示档案。', badge('3 个虚构角色'))}<section class="character-workspace"><aside class="character-list-panel"><label class="search-field">${icon('search')}<input id="character-search" type="search" value="${escapeHTML(state.query)}" placeholder="搜索角色 / 职业" aria-label="搜索示例角色" maxlength="60"></label><div class="character-list" aria-label="角色选择">${filtered.length ? filtered.map(character => `<button class="character-list-item ${c.id === character.id ? 'active' : ''}" data-action="select" data-id="${character.id}" aria-pressed="${c.id === character.id}"><span class="character-avatar theme-${character.theme}">${character.initials}</span><span><strong>${character.name}</strong><small>${character.job}</small></span><b>${character.level}</b></button>`).join('') : '<div class="empty-state">'+icon('search')+'<strong>没有找到角色</strong><p>试试角色名或「鬼剑士」。</p><button class="text-button" data-action="clear-search">清空搜索</button></div>'}</div><div class="list-note">${icon('shield')} 当前仅为固定演示账号</div></aside><article class="character-detail"><div class="detail-hero theme-${c.theme}"><div class="detail-title"><div class="eyebrow">${c.family} · 样例角色</div><h2>${c.name}</h2><p><b>Lv. ${c.level}</b><span>${c.job}</span></p><div class="detail-chips"><span>${c.combat}</span><span>在线状态未知</span></div><div class="detail-fame">${icon('diamond')}<div><span>示例装备</span><strong>${c.equipment.length} 件</strong></div></div></div><div class="detail-art">${characterArt(c, 'detail')}</div></div><div class="detail-content">${characterStatusPanel(state, c)}<div class="detail-bar"><div class="tabs" aria-label="详情面板">${[['stats', '角色属性'], ['equipment', '装备预览']].map(([tab, label]) => `<button class="tab ${state.detailTab === tab ? 'active' : ''}" data-action="tab" data-tab="${tab}" aria-pressed="${state.detailTab === tab}">${label}</button>`).join('')}</div>${badge('示例面板')}</div><div id="detail-panel" aria-label="${state.detailTab === 'stats' ? '角色属性' : '装备预览'}">${state.detailTab === 'stats' ? statPanel(c) : equipmentPanel(c)}</div></div></article></section>`;
}
function announcementsView() { return `${pageHeading('NOTICE BOARD', '公告中心', '了解门户的演示范围、数据边界与下一步计划。')}<section class="notice-feature"><span class="notice-feature-icon">${icon('bell')}</span><div><div class="eyebrow">A NEW CHAPTER</div><h2>从一份清晰的角色档案开始。</h2><p>这里的公告来自本原型，不是游戏运营方的实时公告。</p></div>${badge('原型内容')}</section><section class="announcements-panel full-notices">${sectionHeading('全部公告', '3 条 · 点击阅读完整说明')}<div class="announcement-list">${announcementRows()}</div></section>`; }
function connectionView() { return `${pageHeading('CONNECTION & SAFETY', '先做好边界，再开始冒险', '当前是一个全新独立项目。没有真实登录，也没有游戏数据连接。')}<div class="connection-layout"><section class="connection-card"><div class="large-status-icon">${icon('plug')}</div><span class="eyebrow">CONNECTION STATUS</span><h2>未连接游戏服务器</h2><p>游戏是否在线：<b>未知</b><br>数据来源：<b>静态演示快照</b></p><div class="connection-items"><span>${icon('shield')} 不收集真实账号或密码</span><span>${icon('eye')} 不读取、不修改游戏数据库</span><span>${icon('user')} 不建立真实玩家登录会话</span></div></section><section class="roadmap-panel">${sectionHeading('从原型到真实门户', '每一步都要可验证，而不是把演示当作完成。')}<ol class="roadmap"><li class="done"><span>01</span><div><strong>交互原型 <em>当前阶段</em></strong><p>确认登录入口、本人角色展示与信息层级。所有内容均为样例。</p></div></li><li><span>02</span><div><strong>独立 Web 登录</strong><p>后端校验真实身份并创建 Web 会话，不复用可能替换游戏 token 的登录流程。</p></div></li><li><span>03</span><div><strong>本人数据的只读接口</strong><p>服务端逐次校验账号与角色归属；确认数据字段后再提供角色与装备信息。</p></div></li><li><span>04</span><div><strong>联机验证与部署</strong><p>待游戏服务可用后验证兼容性、会话隔离、越权防护与连接状态。</p></div></li></ol></section></div><div class="scope-note">${icon('info')} 本阶段不包含 GM、充值、交易或背包修改。页面的「演示会话」不是身份认证，不能用于保护真实数据。</div>`; }
function statusToggle(state) {
  const simulated = state.statusSnapshot?.source === 'simulation';
  return `<button class="status-toggle ${simulated ? 'is-on' : ''}" data-action="status-toggle" role="switch" aria-checked="${simulated}" aria-label="查看模拟状态"><span class="toggle-track" aria-hidden="true"><i></i></span><span>查看模拟状态</span></button>`;
}
function characterStatusPanel(state, character) {
  const snapshot = state.statusSnapshot;
  const simulated = snapshot?.source === 'simulation';
  const status = snapshot?.characters.find(item => item.characterId === character.id);
  return `<section class="character-status-section" aria-label="本人角色位置与深渊记录"><div class="character-status-heading"><h3>位置与深渊记录</h3>${statusToggle(state)}</div><div class="character-status-values"><div><span>角色所在位置 ${simulated ? '· 模拟' : ''}</span><strong>${status?.location ? escapeHTML(status.location) : '未知'}</strong></div><div><span>今日深渊 ${simulated ? '· 模拟' : ''}</span><strong>${status?.abyssRuns == null ? '未知' : `${status.abyssRuns} 次`}</strong></div></div><p class="status-detail-note">${simulated ? `静态虚构样例 · 示例日期 ${snapshot.exampleDate}，非真实今日记录。` : '未接入位置或深渊数据；未知不是 0 次。'} 已选：按成功入场计次。未打完或退出也计，失败入场不计；同局重复通知或重连不重复计次。</p></section>`;
}
function leaderboardView(state) {
  const snapshot = state.leaderboardSnapshot;
  const simulated = snapshot.source === 'simulation';
  const isLevel = ['enhancement', 'amplification'].includes(snapshot.category);
  const raidName = snapshot.raid === 'anton' ? '安徒恩' : '卢克';
  return `${pageHeading('HALL OF ADVENTURERS', '排行榜', '记录冒险的足迹，也铭记每一次突破。当前未接入真实榜单。', `<button class="status-toggle ${simulated ? 'is-on' : ''}" data-action="leaderboard-simulate" role="switch" aria-checked="${simulated}"><span class="toggle-track" aria-hidden="true"><i></i></span><span>查看演示榜单</span></button>`)}
    <section class="leaderboard-panel"><div class="leaderboard-tabs" aria-label="榜单类型">${Object.entries(leaderboardCategories).map(([category, info]) => `<button class="leaderboard-tab ${category === snapshot.category ? 'active' : ''}" data-action="leaderboard-category" data-category="${category}" aria-pressed="${category === snapshot.category}">${icon(category === 'raid' ? 'shield' : category === 'abyss' ? 'sword' : 'diamond')}<span>${info.title}</span></button>`).join('')}</div>
    <div class="leaderboard-heading"><div><span class="eyebrow">${isLevel ? 'HISTORICAL PEAK · EXAMPLE' : 'ALL-TIME · EXAMPLE'}</span><h2>${snapshot.category === 'raid' ? `${raidName} · ` : ''}${snapshot.metric}</h2><p>${isLevel ? '展示历史最高等级 +N，不是强化或增幅的操作次数。' : snapshot.category === 'abyss' ? '累计成功进入深渊的次数；未打完或退出也计，失败入场不计。' : '按团本分别展示累计成功攻坚次数，不将不同团本合并。'}</p></div>${snapshot.category === 'raid' ? `<label class="raid-select">团本样例<select id="leaderboard-raid" aria-label="选择团本样例"><option value="anton" ${snapshot.raid === 'anton' ? 'selected' : ''}>安徒恩</option><option value="luke" ${snapshot.raid === 'luke' ? 'selected' : ''}>卢克</option></select></label>` : badge(snapshot.scope)}</div>
    <div class="leaderboard-mode-note ${simulated ? 'simulated' : ''}">${icon('info')}<span>${simulated ? `演示榜单 · 全部为独立虚构角色与数值 · 示例日期 ${snapshot.exampleDate}，不是实时排名。` : '真实数据未接入，当前没有可用排名。开启「查看演示榜单」仅预览虚构样例。'} ${snapshot.category === 'raid' ? '团本名称仅用于 DNF90 界面示例，不表示服务器已支持。' : ''}</span></div>
    ${simulated ? `<div class="leaderboard-table-wrap"><table class="leaderboard-table"><caption class="visually-hidden">${snapshot.title}演示排行榜</caption><thead><tr><th scope="col">排名</th><th scope="col">角色 / 职业等级</th>${isLevel ? '<th scope="col">关联装备 · 示例</th>' : ''}<th scope="col">${isLevel ? '历史最高等级' : '累计次数 · 示例'}</th></tr></thead><tbody>${snapshot.entries.map(entry => `<tr><td><span class="rank-number ${entry.rank <= 3 ? 'top-rank' : ''}">${String(entry.rank).padStart(2, '0')}</span></td><th scope="row"><strong>${escapeHTML(entry.name)}</strong><span>${escapeHTML(entry.job)} · Lv. ${entry.level}</span></th>${isLevel ? `<td class="ranking-equipment">${escapeHTML(entry.equipment)}<small>虚构历史记录，非当前装备快照</small></td>` : ''}<td class="ranking-value"><strong>${isLevel ? `+${entry.value}` : n(entry.value)}</strong><span>${snapshot.unit}</span></td></tr>`).join('')}</tbody></table></div>` : `<div class="leaderboard-empty">${icon('diamond')}<h3>榜单暂未接入</h3><p>${isLevel ? '尚无经过验证的历史最高等级记录。' : '尚无经过验证的累计次数记录。'}<br>未知不是 0，也不会用你的角色样例推算全服排名。</p></div>`}
    <div class="leaderboard-footnote"><span>同分同名次（1、2、2、4）；同分按固定样例顺序展示。</span><span>${snapshot.scope} · 无奖励或领取操作</span></div></section><p class="scope-note">${icon('shield')}${isLevel ? '历史最高强化/增幅必须来自服务端确认的历史记录，不能用当前装备等级冒充。此处仅为静态样例。' : snapshot.category === 'abyss' ? '按服务端确认的成功深渊入场计次，同一局重复通知/重连不重复计。普通通关与疲劳消耗不能替代；真实统计尚未接入。' : '团本成功攻坚需要独立、可验证且去重的结算记录。当前仅按累计榜演示，不预设今日或周榜的换日规则。'}</p>`;
}
function floatingStatus(state) {
  const snapshot = state.statusSnapshot;
  const simulated = snapshot?.source === 'simulation';
  return `<div id="status-floating" class="status-floating"><button id="status-launcher" class="status-launcher ${simulated ? 'simulated' : ''}" data-action="widget" aria-expanded="${state.widgetOpen}" aria-controls="status-popover" aria-describedby="floating-instructions" aria-label="服务器状态，点击展开，可拖动">${icon('plug')}<span>服务器</span><i aria-hidden="true"></i></button><span id="floating-instructions" class="visually-hidden">点击或按 Enter 展开。可拖动移动；聚焦后按方向键移动，Home 恢复右下角。</span>${state.widgetOpen ? `<section id="status-popover" class="status-popover" aria-labelledby="status-popover-title"><div class="status-popover-header"><div><span class="eyebrow">SERVER STATUS</span><h2 id="status-popover-title">服务器状态</h2></div><button class="icon-button" data-action="close-widget" aria-label="收起服务器状态">${icon('close')}</button></div><div class="floating-status-metrics"><div><span>游戏服务</span><strong>${simulated ? '运行中 <em>模拟</em>' : '未知'}</strong></div><div><span>在线人数</span><strong>${snapshot?.onlinePlayers == null ? '未知' : `${n(snapshot.onlinePlayers)} <small>人 · 模拟</small>`}</strong></div></div><p class="floating-connection-note">${icon('info')} ${simulated ? `静态虚构样例 · 示例日期 ${snapshot.exampleDate}` : '账号接口未接入 · 游戏服务未连接'}</p><div class="floating-controls">${statusToggle(state)}<button id="players-details-button" class="text-button" data-action="players">详情 ${icon('arrow')}</button></div><p class="floating-footer-note">${simulated ? '演示全服名单，非真实玩家或实时状态。' : '无有效数据，未知不等于 0 人。'}</p></section>` : ''}</div>`;
}
function playersDialog(state) {
  if (!state.playersOpen) return '';
  const snapshot = state.statusSnapshot;
  const simulated = snapshot?.source === 'simulation';
  return `<dialog id="players-dialog" class="players-dialog" aria-labelledby="players-dialog-title"><header class="players-dialog-header"><div><span class="eyebrow">SERVER PLAYERS</span><h2 id="players-dialog-title">玩家动态</h2></div><button class="icon-button" data-action="close-players" aria-label="关闭玩家动态，返回状态小窗">${icon('close')}</button></header><div class="players-dialog-toolbar">${badge(simulated ? '演示全服名单 · 非真实' : '未接入 · 名单未知')}${statusToggle(state)}</div><div class="players-dialog-body">${simulated ? `<p class="players-roster-note">以下 ${snapshot.publicPlayers.length} 位玩家全部为独立虚构样例，不是你的角色列表，也不代表真实在线玩家。示例日期 ${snapshot.exampleDate}。</p><div class="players-roster" role="table" aria-label="虚构玩家名字、职业等级与当前活动"><div class="players-roster-heading" role="row"><span role="columnheader">玩家</span><span role="columnheader">职业 / 等级</span><span role="columnheader">正在做什么</span></div>${snapshot.publicPlayers.map(player => `<div class="players-roster-row" role="row"><strong role="cell">${escapeHTML(player.name)}<small>虚构玩家</small></strong><span role="cell">${escapeHTML(player.job)}<small>Lv. ${player.level}</small></span><span role="cell" class="player-activity ${player.activity === '深渊中' ? 'abyss' : ''}"><i aria-hidden="true"></i>${escapeHTML(player.activity)}</span></div>`).join('')}</div>` : `<div class="players-empty">${icon('user')}<h3>尚无可用的玩家动态</h3><p>服务器未接入，在线人数与玩家活动均未知。<br>开启「查看模拟状态」可预览独立虚构名单。</p></div>`}<p class="players-privacy-note">${icon('shield')} 只展示名字、职业、等级与活动。不展示账号标识、资产、装备或个人深渊记录；admin 演示登录不授予 GM 权限。</p></div><footer class="players-dialog-footer"><span>未连接游戏服务器 · 非实时数据</span><button class="secondary-button" data-action="close-players">返回状态小窗</button></footer></dialog>`;
}
function modal(state) {
  const announcement = announcements.find(a => a.id === state.activeAnnouncement);
  return announcement ? `<dialog id="announcement-dialog" aria-labelledby="announcement-title"><div class="dialog-top"><span class="announcement-type gold">${announcement.type}</span><button class="icon-button" data-action="close-announcement" aria-label="关闭公告">${icon('close')}</button></div><h2 id="announcement-title">${announcement.title}</h2><p class="dialog-date">${announcement.date} · 本原型内容</p><p class="dialog-body">${announcement.body}</p><div class="dialog-footer"><span>演示内容 · 非实时游戏公告</span><button class="secondary-button" data-action="close-announcement">知道了</button></div></dialog>` : '';
}
export function renderApp(state) {
  if (!state.signedIn) return login();
  const currentNav = navItems.find(item => item[0] === state.view);
  const content = state.view === 'characters' ? charactersView(state) : state.view === 'leaderboard' ? leaderboardView(state) : state.view === 'announcements' ? announcementsView() : state.view === 'connection' ? connectionView() : overview(state);
  return `<div class="app-shell">${sidebar(state)}<div class="main-shell"><header class="topbar"><div class="breadcrumbs"><button class="icon-button mobile-menu" data-action="menu" aria-label="${state.menuOpen ? '关闭导航' : '打开导航'}" aria-expanded="${state.menuOpen}">${icon(state.menuOpen ? 'close' : 'menu')}</button><span>玩家中心</span>${icon('chevron')}<strong>${currentNav[2]}</strong></div><div class="topbar-right"><span class="server-label">演示大区 <i></i> 非真实区服</span><button class="icon-button notifications" data-action="nav" data-view="announcements" aria-label="阅读 3 条原型公告">${icon('bell')}<span></span></button><span class="avatar mini" title="固定演示账号">旅</span></div></header><div class="demo-banner">${icon('info')}<span><strong>演示模式</strong> 所有角色与数值均为虚构样例，未连接游戏服务器。</span><button data-action="nav" data-view="connection">了解接入边界 ${icon('arrow')}</button></div><main id="main-content" class="main-content">${content}</main><footer class="app-footer"><span>阿拉德档案 <i> / </i> 非官方 DNF 玩家门户概念演示</span><span>${state.refreshed ? '已重新载入演示快照' : '静态演示快照'} · 非实时数据</span></footer></div></div>${floatingStatus(state)}${playersDialog(state)}${modal(state)}`;
}
